style.css:
@-moz-document url-prefix("https://vk.com") {
/*Head*/
#page_header_cont {
    height: 42px;
    background: #4a76a8;
    border-bottom: 1px solid #4872a3;
}
header#page_header {
    width: 970px;
    background: #4a76a8;
}
/*Logo*/
.TopHomeLink {
    background: url(https://vk.com/images/svg_icons/ic_head_logo.svg) no-repeat 50% / contain;
    height: 19px;
    width: 34px;
    margin: 0px 125px 0 0;
    border-radius: 0px;
}
a.TopHomeLink > svg {
    display: none;
}


/*Search*/
#page_header .vkuiSearch__field {
    border: 0;
    box-sizing: border-box;
    padding: 6px 6px 6px 0px;
    margin: 7px 0;
    height: 28px;
    line-height: 16px;
    width: 230px;
    border-radius: 14px;
    -o-transition: background-color 0.05s, color 0.05s;
    transition: background-color 0.05s, color 0.05s;
    background: #224b7a url(https://vk.com/images/svg_icons/ic_head_loupe.svg) no-repeat;
    border-left: 8px solid transparent;
    background-position: left 8px;
}
input#search-\:r0\: {
    padding-left: 20px;
    font-size: 13px;
    margin-top: -1px;
}
.vkuiSearch__input > svg{
    display: none;
}

/*Head Player*/
.top_audio_player_title {
    color: #d9e2ec !important;
}
#page_body {
    margin-top: 43px;
}
.TopNavBtn .TopNavBtn__icon {
    color: #d9e2ec !important;
}

.top_audio_player_btn svg {
    color: #d9e2ec !important;
}



:root, .vkui--vkBase--light, .vkui--vkBase--dark, .vkui--vkCom--light, .vkui--vkCom--dark, [scheme="vkcom_light"], [scheme="vkcom_dark"], [scheme="bright_light"], [scheme="space_gray"]{
    --vkui--size_check_border_radius--regular: 0px;
    --vkui--size_border_radius_paper--regular: 0px;
    --vkui--size_border_radius_promo--regular: 0px;
}


/*Left Column*/
/*Profile avatar*/
.ProfileHeader.ProfileHeader--withSnowballs.ProfileHeader--noCover {
    border-radius: 5px;
}
/*Profile Actions*/
a.vkitButton__root--RejCB.vkuiButton.vkuiButton--size-m.vkuiButton--mode-secondary.vkuiButton--appearance-accent.vkuiButton--align-center.vkuiTappable.vkuiTappable--hasPointer-none.vkuiClickable__resetLinkStyle.vkuiClickable__host.vkuiClickable__realClickable.vkui-focus-visible.vkuiRootComponent {
    border-radius: 5px;
}
/*Profile modules*/
.vkuiGroup--mode-card:before, .vkuiGroup--sizeX-regular.vkuiGroup--mode-none:before {
    border-radius: 0px;
}
/*Profile Groups module*/
span.vkuiSimpleCell__children.vkuiHeadline--sizeY-compact.vkuiHeadline--level-1.vkuiTypography.vkuiTypography--normalize.vkuiTypography--weight-3.vkuiRootComponent {
    color: #2a5885;
}
span.vkuiSimpleCell__text.vkuiSimpleCell__subtitle.vkuiFootnote.vkuiTypography.vkuiRootComponent {
    font-size: 12px;
    color: #656565;
}












/*Right column*/
.ProfileInfo {
    padding-bottom: 0;
    border-radius: 5px;
}


/*Profile_name*/
#owner_page_name {
    margin-left: 20px;
}


/*Profile Online*/
.ProfileIndicatorBadge__badgeLastSeen {
    color: #828282 !important;
}


/*Profile status*/
.page_current_info.current_text, [style="width: 100%;"] > #page_current_info, .ProfileInfo__broadcast {
    margin-left: 20px;
}
div#page_current_info {
    padding-bottom: 10px !important;
}
.page_current_info.current_text, [style="width: 100%;"] > #page_current_info, .ProfileInfo__broadcast {
    width: 93%;
}


/*Profile info short*/
.profile_info_short {
    padding-left: 20px;
    width: 515px;
}
.profile_info .label {
    color: #828282;
}


/*Profile counters*/
.page_counter:not([href*="bugs?act="]) {
    padding-top: 0px !important;
}
.page_counter .counter .label:hover {
    color: #42648b !important;
}
.ProfileHeaderButton >a[href*="/im"] >span:before {
    font-size: 13px;
}
.counts_module {
    border-radius: 0px;
}


/*Module photos*/
section.vkitGroup__group--f8Opf.vkitGroup__groupPaddingM--1Ck31.vkitGroup__groupModeCard--jNpCl.vkuiInternalGroupCard.vkuiInternalGroup.vkuiGroup.vkuiGroup--sizeX-regular.vkuiGroup--mode-card.vkuiInternalGroup--mode-card.vkuiGroup--padding-m.vkuiRootComponent {
    border-radius: 5px;
}




.top_profile_name {
    padding-right: 10px;
    color: #fff;
}





/*Buttons*/
a.vkitButton__root--RejCB.vkuiButton.vkuiButton--size-m.vkuiButton--mode-primary.vkuiButton--appearance-accent.vkuiButton--align-center.vkuiTappable.vkuiTappable--hasPointer-none.vkuiClickable__resetLinkStyle.vkuiClickable__host.vkuiClickable__realClickable.vkui-focus-visible.vkuiRootComponent {
    border-radius: 5px;
    border: none;
}
button.vkitButton__root--RejCB.vkuiButton.vkuiButton--size-m.vkuiButton--mode-secondary.vkuiButton--appearance-accent.vkuiButton--align-center.vkuiButton--with-icon.vkuiButton--singleIcon.vkuiTappable.vkuiTappable--hasPointer-none.vkuiClickable__resetButtonStyle.vkuiClickable__host.vkuiClickable__realClickable.vkui-focus-visible.vkuiRootComponent {
    border-radius: 5px;
}

button{
    border-radius: 5px;
}







/*GROUP PAGE*/
#public .page_block.redesigned-cover-block {
    margin-top: 50px;
}
#public .redesigned-group-info {
    display: block;
    width: 305px;
}
#public .redesigned-group-cover {
    display: none;
}
#public .AvatarRich--shadow::after{
    box-shadow: none;
}
#public .redesigned-group-avatar img.AvatarRich__img {
    border-radius: 2px;
    width: 200px;
    height: 200px;
}
#public .redesigned-group-avatar-outline {
    border: 0;
}
#public span.AvatarRich.AvatarRich--sz-100.AvatarRich--shadow.redesigned-group-avatar-outline {
    width: 200px !important;
    height: 200px !important;
}
#public .page_block.redesigned-cover-block {
    margin-top: 50px;
    width: 38%;
    position: relative;
    left: 565px;
}
#public #wide_column {
    margin-top: -417px;
}
#public .narrow_column.fixed {
    position: relative !important;
}
#public a.redesigned-group-avatar {
    width: 200px;
    height: 200px;
    position: relative;
    left: 58px;
    top: 75px;
    margin-bottom: 100px;
}
#public .narrow_column {
    margin-top: 0px !important;
}
#public #page_subscribers {
    text-align: center;
    margin: 10px 0;
}
#public .redesigned-group-info__main {
    flex: 1;
    margin-right: 0;
}
#public h1.page_name {
    text-align: center;
    padding: 0px !important;
}
#public .redesigned-group-subscribers {
    margin: 10px 0;
    justify-content: center;
}
#public .redesigned-group-info__actions .page_actions {
    justify-content: center;
}













